insert into public.content_policy_versions(version,terms,content_policy,active)
select '2026-10-15',terms,'[{"title":"1. Content covered by this policy","body":"This policy applies to recipes, photos, comments, reviews, profiles and messages. You must have permission to share your content. Honest low ratings, respectful criticism, different tastes and ordinary cooking failures are not policy violations."},{"title":"2. Prohibited content and behaviour","body":"Do not post harassment, threats, bullying, hateful discrimination or incitement to violence; sexual exploitation, explicit sexual content, non-consensual sexual images or child sexual abuse content; private identifying information or private conversations without permission; scams, phishing, spam or deceptive promotions; content that infringes another person''s rights or impersonates them; instructions that encourage harm, clearly dangerous cooking practices or unsupported promises to cure disease; manipulated reviews or engagement; or content or accounts intended to evade moderation."},{"title":"3. Reporting and responsibility","body":"Report recipes, reviews, comments and users in the app, and block users when needed. Designated Pickle administrators review reports. The responsible Pickle operator reviews long or permanent suspensions and reversals. Reviewers must not handle cases in which they are the reported person or reporter. Contact admin@getpickleapp.com for additional information or questions."},{"title":"4. Review process and response targets","body":"Reports are received, prioritised and grouped by incident. Reviewers consider the full context, relevant evidence, established previous violations and any additional information needed before deciding. Content may be provisionally hidden to prevent ongoing harm without confirming a violation. Urgent and high-priority cases have a 24-hour first-review target; ordinary reports have a 3-business-day target. These are operational goals, not guaranteed response times."},{"title":"5. Content actions","body":"Possible outcomes include no violation confirmed, requests for changes or information, provisional hiding, hiding, removal and restoration. Content removal means removal from the service''s public display; it is different from irreversible deletion of every stored record. A report or allegation alone does not establish infringement or unsafe conduct. Report count alone never determines a sanction."},{"title":"6. Account warnings and restrictions","body":"A minor first confirmed incident normally receives a warning and an appropriate content action. Repeated confirmed incidents may lead to a 3-day restriction on publishing, photo uploads and messages, or a 7-day or 30-day suspension that also restricts social interactions. Critical risk may lead to a provisional 24-hour suspension and immediate content hiding while a long or permanent suspension is reviewed. Severe violations or proven repeated evasion may justify permanent suspension without prior warnings. Long and permanent suspensions require a separate final approval step. Suspended accounts may still view notices, report safety concerns, appeal, delete their own content and request account deletion."},{"title":"7. Repeat violations, expiry and false reports","body":"Repeated violations are assessed using confirmed incidents within the preceding 90 days. Duplicate reports about the same incident count once; dismissed, provisional and overturned findings do not count. Restrictions expire at the stated end time; permanent suspension has no automatic end date. Proven malicious false reporting may lead to a warning or temporary reporting restriction. A report that is merely dismissed does not justify restricting the reporter."},{"title":"8. Notices, privacy and appeals","body":"Authors receive the affected content or account action, policy clause, public reason and any restriction duration through in-app notices and email. Reporter identity and internal administrator notes are not shared with the author. Reporters receive only a limited review result. You may appeal within 14 days of the decision notice through Profile > Account status & appeals. We aim to review appeals within 7 business days, using another uninvolved reviewer where available. If the decision was mistaken, its violation count and restriction are cancelled and content is restored unless another standing decision still applies."},{"title":"9. Records and account deletion","body":"Review decisions, responsible administrators, reasons, times and appeal results are recorded for oversight. Access to internal evidence and notes is restricted to authorised administrators. Account suspension is different from account deletion. Evidence-retention periods and irreversible erasure procedures will be defined separately with the privacy policy; this policy does not authorise indefinite evidence retention."}]'::jsonb,false from public.content_policy_versions where active;
update public.content_policy_versions set active=false where active;
update public.content_policy_versions set active=true where version='2026-10-15';

